#include <windows.h>
#include <bcrypt.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>

#pragma comment(lib, "bcrypt.lib")

namespace device {
namespace {

// Indexed by CardStyle. Generated by tools/make-images.ps1.
constexpr CardArt kArt[] = {
    {"gaming_trio", 46, 550, 76, 88},     // CardStyle::GamingTrio
    {"vanguard", 47, 540, 76, 87},        // CardStyle::Vanguard
    {"suprim", 61, 531, 77, 88},          // CardStyle::Suprim
    {"suprim_liquid", 51, 236, 60, 72},   // CardStyle::SuprimLiquid
    {"gaming", 63, 531, 49, 64},          // CardStyle::Gaming
};
static_assert(sizeof(kArt) / sizeof(kArt[0]) == kCardStyleCount, "one entry per CardStyle");

char* Dup(const std::string& s)
{
    return _strdup(s.c_str());
}

std::wstring Widen(const char* s)
{
    std::wstring w;
    for (; *s; ++s)
        w += static_cast<wchar_t>(*s == '/' ? '\\' : *s);   // our paths are ASCII
    return w;
}

cue_abi::Image* MakeImage(const std::string& relPath, const std::wstring& pluginDir)
{
    std::wstring full = pluginDir + L"\\" + Widen(relPath.c_str());
    auto* img = new cue_abi::Image;
    img->path = Dup(relPath);
    img->hash = Dup(Sha256File(full));
    if (!*img->hash)
        Log("image missing: %s", relPath.c_str());
    return img;
}

// Only ever called with images from MakeImage(), which are never null.
void FreeImage(cue_abi::Image* img)
{
    free(img->path);
    free(img->hash);
    delete img;
}

uint8_t ClampChannel(int64_t v)
{
    return static_cast<uint8_t>(v < 0 ? 0 : (v > 255 ? 255 : v));
}

} // namespace

const CardArt& ArtFor(CardStyle style)
{
    return kArt[static_cast<int>(style)];
}

std::string ImagePath(CardStyle style, const char* file)
{
    return std::string("images/") + ArtFor(style).folder + "/" + file;
}

std::string DeviceIdFor(const nvi2c::GpuInfo& gpu)
{
    char id[64];
    snprintf(id, sizeof(id), "MSIGPU_%04X%04X_%04X%04X", gpu.vendor, gpu.device, gpu.subVendor, gpu.subDevice);
    return id;
}

std::string Sha256File(const std::wstring& path)
{
    FILE* f = nullptr;
    if (_wfopen_s(&f, path.c_str(), L"rb") != 0)
        return "";

    BCRYPT_ALG_HANDLE alg = nullptr;
    BCRYPT_HASH_HANDLE hash = nullptr;
    unsigned char digest[32] = {};
    bool ok = BCryptOpenAlgorithmProvider(&alg, BCRYPT_SHA256_ALGORITHM, nullptr, 0) == 0 &&
              BCryptCreateHash(alg, &hash, nullptr, 0, nullptr, 0, 0) == 0;
    unsigned char buf[16384];
    size_t n;
    while (ok && (n = fread(buf, 1, sizeof(buf), f)) > 0)
        ok = BCryptHashData(hash, buf, static_cast<ULONG>(n), 0) == 0;
    ok = ok && !ferror(f) && BCryptFinishHash(hash, digest, sizeof(digest), 0) == 0;
    BCryptDestroyHash(hash);
    BCryptCloseAlgorithmProvider(alg, 0);
    fclose(f);

    std::string hex;
    char h[3];
    for (unsigned char c : digest) {
        snprintf(h, sizeof(h), "%02x", c);
        hex += h;
    }
    return ok ? hex : "";
}

cue_abi::DeviceInfo* BuildDeviceInfo(const std::string& name, const std::string& deviceId, int32_t deviceType,
                                     int32_t ledCount, CardStyle style, const std::wstring& pluginDir)
{
    auto* info = new cue_abi::DeviceInfo{};
    info->deviceName = Dup(name);
    info->deviceType = deviceType;
    info->deviceId = Dup(deviceId);
    info->numberOfDeviceView = 1;
    info->thumbnail = MakeImage(ImagePath(style, "thumbnail.png"), pluginDir);
    info->promoImage = MakeImage(ImagePath(style, "promo.png"), pluginDir);

    info->ledPositions = new cue_abi::LedPositions;
    info->ledPositions->numberOfLed = ledCount;
    info->ledPositions->ledPosition = new cue_abi::LedPosition[static_cast<size_t>(ledCount)];
    for (int32_t i = 0; i < ledCount; ++i) {
        auto& p = info->ledPositions->ledPosition[i];
        p = {};
        p.ledId = cue_abi::kLedGpuZone1 + i;
        p.x = 10.0 + 20.0 * i;
        p.y = 10.0;
    }
    return info;
}

void FreeDeviceInfo(cue_abi::DeviceInfo* info)
{
    if (!info)
        return;
    free(info->deviceName);
    free(info->deviceId);
    FreeImage(info->thumbnail);
    FreeImage(info->promoImage);
    delete[] info->ledPositions->ledPosition;
    delete info->ledPositions;
    delete info;
}

cue_abi::DeviceView* BuildDeviceView(int32_t ledCount, CardStyle style, const std::wstring& pluginDir)
{
    const CardArt& art = ArtFor(style);
    auto* view = new cue_abi::DeviceView{};
    view->view = MakeImage(ImagePath(style, "device_view.png"), pluginDir);
    view->mask = MakeImage(ImagePath(style, "device_view_mask.png"), pluginDir);
    view->actionZones = nullptr;
    view->ledView = new cue_abi::LedViews;
    view->ledView->numberOfLed = ledCount;
    view->ledView->view = new cue_abi::LedView[static_cast<size_t>(ledCount)];

    // Equal zones with a 2 px gap between neighbours.
    const double step = double(art.barRight - art.barLeft) / ledCount;
    for (int32_t i = 0; i < ledCount; ++i) {
        int x0 = art.barLeft + int(step * i) + (i > 0 ? 2 : 0);
        int x1 = art.barLeft + int(step * (i + 1)) - (i + 1 < ledCount ? 2 : 0);
        char path[160];
        snprintf(path, sizeof(path), "M %d %d L %d %d L %d %d L %d %d Z", x0, art.barTop, x1, art.barTop, x1,
                 art.barBottom, x0, art.barBottom);
        auto& v = view->ledView->view[i];
        v.ledId = cue_abi::kLedGpuZone1 + i;
        v.path = Dup(path);
        v.appearance = cue_abi::ZoneAppearance::SvgPath;
        v.text = nullptr;
    }
    return view;
}

void FreeDeviceView(cue_abi::DeviceView* view)
{
    if (!view)
        return;
    FreeImage(view->view);
    FreeImage(view->mask);
    for (int32_t i = 0; i < view->ledView->numberOfLed; ++i)
        free(view->ledView->view[i].path);
    delete[] view->ledView->view;
    delete view->ledView;
    delete view;
}

bool AverageColor(const cue_abi::LedColor* colors, int32_t size, int32_t ledCount, Rgb& out)
{
    if (!colors || size <= 0)
        return false;

    int64_t r = 0;
    int64_t g = 0;
    int64_t b = 0;
    int64_t n = 0;
    for (int32_t i = 0; i < size; ++i) {
        const auto& c = colors[i];
        if (c.ledId < cue_abi::kLedGpuZone1 || c.ledId >= cue_abi::kLedGpuZone1 + ledCount)
            continue;
        r += ClampChannel(c.r);
        g += ClampChannel(c.g);
        b += ClampChannel(c.b);
        ++n;
    }
    if (n == 0)
        return false;

    out = {static_cast<uint8_t>(r / n), static_cast<uint8_t>(g / n), static_cast<uint8_t>(b / n)};
    return true;
}

} // namespace device
